const state={items:[],selected:new Set(),neededFrom:"",sort:"date"};
const euro=n=>n==null?"Da verificare":new Intl.NumberFormat("it-IT",{style:"currency",currency:"EUR",maximumFractionDigits:0}).format(n);
const fmtDate=s=>{if(!s)return null;const d=new Date(`${s}T12:00:00`);return new Intl.DateTimeFormat("it-IT",{day:"numeric",month:"long",year:"numeric"}).format(d)};
const availabilityText=x=>x.availability?.availableLabel||fmtDate(x.availability?.availableFrom)||"Da verificare";
const statusText=x=>({confirmed:"Confermata",to_reconfirm:"Da riconfermare",unavailable:"Non disponibile",unknown:"Da riconfermare"}[x.availability?.status]||"Da riconfermare");
const yesno=v=>v?"Sì":"Da verificare";
const costText=x=>x.realMonthlyCostStatus==="complete"?euro(x.realMonthlyCost):x.realMonthlyCostStatus==="minimum_known"?`almeno ${euro(x.realMonthlyCost)}`:"Da verificare";
const distanceText=x=>x.campusReference?.distanceKm==null?"Da calcolare":`${Number(x.campusReference.distanceKm).toLocaleString("it-IT",{minimumFractionDigits:2,maximumFractionDigits:2})} km in linea d’aria`;
function validationScore(x){const v=x.validation||{};return [v.contactProvided,v.priceDeclared,v.expensesDeclared,v.contractDeclared,v.depositDeclared,v.utilitiesDeclared].filter(Boolean).length;}
function validationText(x){return `${validationScore(x)}/6 dati dichiarati`}
function dateCompatibility(x){if(!state.neededFrom)return {rank:0,label:""};if(x.availability?.status==="unavailable")return {rank:3,label:"Non disponibile"};const a=x.availability?.availableFrom;if(!a)return {rank:2,label:"Data da verificare"};return a<=state.neededFrom?{rank:0,label:"Compatibile con la tua data"}:{rank:1,label:`Disponibile solo dal ${availabilityText(x)}`};}
function visibleItems(){return [...state.items].sort((a,b)=>{if(state.sort==="price")return (a.realMonthlyCost??Infinity)-(b.realMonthlyCost??Infinity);if(state.sort==="distance")return (a.campusReference?.distanceKm??Infinity)-(b.campusReference?.distanceKm??Infinity);if(state.sort==="validation")return validationScore(b)-validationScore(a);if(state.sort==="availability")return String(a.availability?.availableFrom||"9999").localeCompare(String(b.availability?.availableFrom||"9999"));return dateCompatibility(a).rank-dateCompatibility(b).rank;});}
function setNeededFrom(v){state.neededFrom=v;render();}function setSort(v){state.sort=v;render();}
function render(){const root=document.getElementById("v2-root");if(!root)return;root.innerHTML=`<section class="panel"><h2 class="section-title">Trova e confronta</h2><label class="note" for="neededFrom">Mi serve dal</label><input id="neededFrom" type="date" value="${state.neededFrom}" onchange="setNeededFrom(this.value)"><label class="note" for="sort" style="display:block;margin-top:10px">Ordina per</label><select id="sort" onchange="setSort(this.value)"><option value="date" ${state.sort==="date"?"selected":""}>Compatibilità con la mia data</option><option value="price" ${state.sort==="price"?"selected":""}>Costo minimo noto</option><option value="distance" ${state.sort==="distance"?"selected":""}>Distanza dalla sede</option><option value="availability" ${state.sort==="availability"?"selected":""}>Prima disponibilità</option><option value="validation" ${state.sort==="validation"?"selected":""}>Completezza informazioni</option></select><p class="note">La distanza mostrata è geografica in linea d’aria, non una percorrenza stradale. Tempi a piedi/in bici saranno aggiunti solo con routing reale. I criteri ordinano senza escludere rigidamente le alternative.</p></section><section class="panel"><h2 class="section-title">Schede V2 pilota</h2><p class="note">Dataset interno: le schede non autorizzate restano escluse dalla pubblicazione reale.</p></section>`+visibleItems().map(x=>{const c=dateCompatibility(x);return `<section class="card"><div class="eyebrow">${x.city} · prototipo V2</div><div class="title">${x.title}</div><div class="price">${euro(x.price)} <span class="muted">/ mese</span></div><div><span class="badge warn">Costo ${costText(x)}</span><span class="badge warn">${statusText(x)}</span><span class="badge">${distanceText(x)}</span><span class="badge ${validationScore(x)>=4?"":"warn"}">${validationText(x)}</span>${c.label?`<span class="badge ${c.rank===0?"":"warn"}">${c.label}</span>`:""}</div><div class="row"><span>Disponibile dal</span><strong>${availabilityText(x)}</strong></div><div class="row"><span>Ultima conferma</span><strong class="unknown">${x.availability?.confirmedAt?fmtDate(x.availability.confirmedAt):"Da riconfermare"}</strong></div><div class="row"><span>Sede di riferimento</span><strong>${x.campusReference?.campusName||"Da scegliere"}</strong></div><div class="row"><span>Distanza geografica</span><strong>${distanceText(x)}</strong></div><div class="row"><span>Pubblicazione autorizzata</span><strong class="${x.publication?.authorized?"good":"unknown"}">${x.publication?.authorized?"Sì":"No"}</strong></div><div class="row"><span>Canone</span><strong>${yesno(x.validation?.priceDeclared)}</strong></div><div class="row"><span>Spese</span><strong class="${x.validation?.expensesDeclared?"good":"unknown"}">${yesno(x.validation?.expensesDeclared)}</strong></div><div class="row"><span>Contratto</span><strong class="${x.validation?.contractDeclared?"good":"unknown"}">${yesno(x.validation?.contractDeclared)}</strong></div><div class="row"><span>Deposito</span><strong class="${x.validation?.depositDeclared?"good":"unknown"}">${yesno(x.validation?.depositDeclared)}</strong></div><div class="row"><span>Utenze</span><strong class="${x.validation?.utilitiesDeclared?"good":"unknown"}">${yesno(x.validation?.utilitiesDeclared)}</strong></div><label class="note" style="display:flex;gap:8px;align-items:center;margin-top:12px"><input type="checkbox" style="width:auto" ${state.selected.has(x.id)?"checked":""} onchange="toggleCompare('${x.id}',this.checked)"> Aggiungi al confronto</label></section>`}).join("")+comparison();}
function toggleCompare(id,on){const key=Number.isNaN(Number(id))?id:Number(id);on?state.selected.add(key):state.selected.delete(key);if(state.selected.size>3){state.selected.delete(key);alert("Puoi confrontare fino a 3 alloggi.");}render();}
function comparison(){const xs=state.items.filter(x=>state.selected.has(x.id));if(xs.length<2)return"";const row=(label,fn)=>`<div class="row"><span>${label}</span><strong>${xs.map(fn).join(" · ")}</strong></div>`;return `<section class="panel"><h2 class="section-title">Confronto V2</h2>${row("Costo mensile",costText)}${row("Distanza dalla sede",distanceText)}${row("Disponibilità",availabilityText)}${state.neededFrom?row("Rispetto alla tua data",x=>dateCompatibility(x).label):""}${row("Ultima conferma",x=>x.availability?.confirmedAt?fmtDate(x.availability.confirmedAt):"da riconfermare")}${row("Completezza dati",validationText)}${row("Spese",x=>x.validation?.expensesDeclared?"dichiarate":"da verificare")}${row("Contratto",x=>x.validation?.contractDeclared?"dichiarato":"da verificare")}${row("Deposito",x=>x.validation?.depositDeclared?"dichiarato":"da verificare")}${row("Autorizzazione",x=>x.publication?.authorized?"sì":"no")}</section>`;}
async function init(){try{const r=await fetch("../data/listings-v2-pilot.json",{cache:"no-store"});state.items=await r.json();render()}catch(e){document.getElementById("v2-root").innerHTML='<section class="panel"><b>Dataset V2 non disponibile.</b></section>';console.error(e)}}init();